mapper.update:
/* AuthMapper.updateLoginFail 로그인 실패 시 로그인오류건수를 1 올리고, 기준 횟수에 도달하면 계정을 잠금 */
UPDATE TB_USR_M
   SET LGIN_ERR_CNT  = COALESCE(LGIN_ERR_CNT, 0) + 1,
       USR_LOCK_YN   = CASE WHEN COALESCE(LGIN_ERR_CNT, 0) + 1 >= #{maxLoginFailCount} THEN 'Y' ELSE USR_LOCK_YN END,
       USR_LOCK_DTTM = CASE WHEN COALESCE(LGIN_ERR_CNT, 0) + 1 >= #{maxLoginFailCount} THEN CURRENT_TIMESTAMP ELSE USR_LOCK_DTTM END
 WHERE USR_ID = #{usrId}

/* AuthMapper.updateLoginSuccess 로그인 성공 시 로그인오류건수를 0으로 되돌리고 최종접속일시를 기록 */
UPDATE TB_USR_M
   SET LGIN_ERR_CNT  = 0,
       FINA_ACC_DTTM = CURRENT_TIMESTAMP
 WHERE USR_ID = #{usrId}
